import type { Metadata } from "next";
import { notFound } from "next/navigation";
import Breadcrumb from "@/components/header/breadcrumb";
import getMuseumDetail from "@/services/museumDetailService";
import MuseumGallery from "@/components/museums-page/museum-gallery";

export const dynamic = "force-dynamic";

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}): Promise<Metadata> {
  const museum = await getMuseumDetail(params.slug);
  if (!museum) return {};

  return {
    title: museum.meta_title
      ? `${museum.meta_title} - TravelShop Booking`
      : `${museum.name} - TravelShop Booking`,
    description: museum.meta_description
      || (museum.description
        ? museum.description.replace(/<[^>]+>/g, "").slice(0, 160)
        : `Visit ${museum.name}. Explore opening hours and location details.`),
    alternates: {
      canonical: `https://travelshopbooking.com/museum/${params.slug}`,
    },
  };
}

const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

function sanitize(html: string): string {
  if (!html) return "";
  return html
    .replace(/<p>\s*&nbsp;\s*<\/p>/g, "")
    .replace(/<p>\s*<br\s*\/?>\s*<\/p>/g, "")
    .replace(/<p>\s*<\/p>/g, "")
    .replace(/&nbsp;/g, " ");
}

export default async function MuseumDetailPage({
  params,
}: {
  params: { slug: string };
}) {
  const museum = await getMuseumDetail(params.slug);
  if (!museum) notFound();

  const images: { id: number; url: string; thumb_url: string; name: string }[] =
    Array.isArray(museum.images) ? museum.images : Object.values(museum.images ?? {});

  const openingDays: string[] = museum.opening_days ?? [];
  const description = sanitize(museum.description ?? "");
  const locationParts = [museum.location_parent_name, museum.location_name].filter(Boolean);

  return (
    <main className="tw-bg-gray-50 tw-min-h-screen">
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-py-6">
        <Breadcrumb
          items={[
            { pageTitle: "Museums", pageUrl: "/museums" },
            { pageTitle: museum.name, pageUrl: `/museum/${params.slug}` },
          ]}
        />

        {/* Page header */}
        <div className="tw-mb-6">
          <div className="tw-flex tw-flex-wrap tw-items-center tw-gap-3">
            <h1 className="tw-text-2xl tw-font-bold tw-text-gray-900 tw-mb-0">
              {museum.name}
            </h1>
            {museum.type && (
              <span className="tw-inline-flex tw-items-center tw-px-3 tw-py-1 tw-rounded-full tw-text-xs tw-font-semibold tw-tracking-wide tw-uppercase tw-text-white" style={{ backgroundColor: '#854ec9' }}>
                {museum.type.name}
              </span>
            )}
          </div>
          {locationParts.length > 0 && (
            <p className="tw-mt-1 tw-text-gray-500 tw-text-sm tw-flex tw-items-center tw-gap-1" style={{ color: '#854ec9' }}>
              <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" fill="currentColor" viewBox="0 0 16 16">
                <path d="M8 16s6-5.686 6-10A6 6 0 0 0 2 6c0 4.314 6 10 6 10zm0-7a3 3 0 1 1 0-6 3 3 0 0 1 0 6z"/>
              </svg>
              {locationParts.join(", ")}
            </p>
          )}
        </div>

        <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-12 tw-gap-4">
          {/* Left: Gallery */}
          <div className="lg:tw-col-span-7">
            <MuseumGallery images={images} museumName={museum.name} />
          </div>

          {/* Right: Info */}
          <div className="lg:tw-col-span-5">
            <div className="tw-bg-white tw-rounded-xl tw-shadow-sm tw-border tw-border-gray-100 tw-h-full tw-p-6">
              <h2 className="tw-text-base tw-font-semibold tw-text-gray-800 tw-mb-5 tw-pb-3 tw-border-b tw-border-gray-100">
                Museum Information
              </h2>

              <div className="tw-space-y-4">
                {museum.address && (
                  <div className="tw-flex tw-items-start tw-gap-4 tw-py-3 tw-border-b tw-border-gray-100">
                    <span className="tw-shrink-0 tw-w-10 tw-h-10 tw-rounded-full tw-flex tw-items-center tw-justify-center tw-text-white" style={{ backgroundColor: '#854ec9' }}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" fill="currentColor" viewBox="0 0 16 16">
                        <path d="M12.166 8.94c-.524 1.062-1.234 2.12-1.96 3.07A32 32 0 0 1 8 14.58a32 32 0 0 1-2.206-2.57c-.726-.95-1.436-2.008-1.96-3.07C3.304 7.867 3 6.862 3 6a5 5 0 0 1 10 0c0 .862-.305 1.867-.834 2.94zM8 16s6-5.686 6-10A6 6 0 0 0 2 6c0 4.314 6 10 6 10z"/>
                        <path d="M8 8a2 2 0 1 1 0-4 2 2 0 0 1 0 4zm0 1a3 3 0 1 0 0-6 3 3 0 0 0 0 6z"/>
                      </svg>
                    </span>
                    <div>
                      <p className="tw-text-xs tw-font-bold tw-uppercase tw-tracking-widest tw-mb-1" style={{ color: '#854ec9' }}>Address</p>
                      <p className="tw-text-sm tw-font-medium tw-text-gray-800 tw-mb-0 tw-leading-snug">{museum.address}</p>
                    </div>
                  </div>
                )}

                {(museum.opening_time || museum.closing_time) && (
                  <div className="tw-flex tw-items-start tw-gap-4 tw-py-3 tw-border-b tw-border-gray-100">
                    <span className="tw-shrink-0 tw-w-10 tw-h-10 tw-rounded-full tw-flex tw-items-center tw-justify-center tw-text-white" style={{ backgroundColor: '#854ec9' }}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" fill="currentColor" viewBox="0 0 16 16">
                        <path d="M8 3.5a.5.5 0 0 0-1 0V9a.5.5 0 0 0 .252.434l3.5 2a.5.5 0 0 0 .496-.868L8 8.71V3.5z"/>
                        <path d="M8 16A8 8 0 1 0 8 0a8 8 0 0 0 0 16zm7-8A7 7 0 1 1 1 8a7 7 0 0 1 14 0z"/>
                      </svg>
                    </span>
                    <div>
                      <p className="tw-text-xs tw-font-bold tw-uppercase tw-tracking-widest tw-mb-1" style={{ color: '#854ec9' }}>Opening Hours</p>
                      <p className="tw-text-sm tw-font-medium tw-text-gray-800 tw-mb-0">
                        {museum.opening_time && museum.closing_time
                          ? `${museum.opening_time} – ${museum.closing_time}`
                          : museum.opening_time || museum.closing_time}
                      </p>
                    </div>
                  </div>
                )}

                {openingDays.length > 0 && (
                  <div className="tw-flex tw-items-start tw-gap-4 tw-py-3 tw-border-b tw-border-gray-100">
                    <span className="tw-shrink-0 tw-w-10 tw-h-10 tw-rounded-full tw-flex tw-items-center tw-justify-center tw-text-white" style={{ backgroundColor: '#854ec9' }}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" fill="currentColor" viewBox="0 0 16 16">
                        <path d="M3.5 0a.5.5 0 0 1 .5.5V1h8V.5a.5.5 0 0 1 1 0V1h1a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2V3a2 2 0 0 1 2-2h1V.5a.5.5 0 0 1 .5-.5zM1 4v10a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V4H1z"/>
                      </svg>
                    </span>
                    <div className="tw-w-full">
                      <p className="tw-text-xs tw-font-bold tw-uppercase tw-tracking-widest tw-mb-2" style={{ color: '#854ec9' }}>Open Days</p>
                      <div className="tw-flex tw-flex-wrap tw-gap-1.5">
                        {DAYS.map((day) => {
                          const isOpen = openingDays.includes(day) || openingDays.includes(day.toLowerCase());
                          return (
                            <span
                              key={day}
                              className={`tw-inline-block tw-px-2.5 tw-py-1 tw-rounded-lg tw-text-xs tw-font-semibold ${
                                isOpen
                                  ? "tw-text-white"
                                  : "tw-bg-gray-100 tw-text-gray-400"
                              }`}
                              style={isOpen ? { backgroundColor: '#854ec9' } : undefined}
                            >
                              {day.slice(0, 3)}
                            </span>
                          );
                        })}
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Description */}
        {description && (
          <div className="tw-mt-8">
            <h2 className="tw-text-lg tw-font-semibold tw-text-gray-800 tw-mb-4">
              About {museum.name}
            </h2>
            <div className="tw-bg-white tw-rounded-xl tw-shadow-sm tw-border tw-border-gray-100 tw-p-6 tw-text-gray-700 tw-leading-relaxed prose">
              {description.includes("<") ? (
                <div dangerouslySetInnerHTML={{ __html: description }} />
              ) : (
                <p className="tw-mb-0">{description}</p>
              )}
            </div>
          </div>
        )}
      </div>
    </main>
  );
}
