import { apiv3Get } from "@/lib/apiv3";

export default async function getMuseumDetail(id: string | number) {
    if (!process.env.NEXT_PUBLIC_APIV3_URL) return null;

    try {
        const res = await apiv3Get(`/museums/${id}`, { cache: "no-store" });
        if (!res.ok) return null;

        const json = await res.json();
        return json.data ?? null;
    } catch {
        return null;
    }
}
